#include <Wire.h>
#include <Adafruit_BMP280.h>
#include <SoftwareSerial.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// --- Настройки Bluetooth ---
// RX (пин 2) подключается к TX модуля HC-06
// TX (пин 3) подключается к RX модуля HC-06 через делитель напряжения!
SoftwareSerial BTSerial(2, 3); 

// --- Настройки OLED-дисплея ---
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1 // Если у дисплея нет пина RESET, ставим -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// --- Настройки датчика BMP280 ---
Adafruit_BMP280 bmp; 

void setup() {
  Serial.begin(9600);       // Для отладки на ПК
  BTSerial.begin(9600);     // Для связи с Android

  // 1. Инициализация OLED
  // Адрес дисплея обычно 0x3C
  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { 
    Serial.println(F("SSD1306 allocation failed"));
    for(;;); // Если дисплей не найден, останавливаемся
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0,0);
  display.println("System Init...");
  display.display();
  delay(500);

  // 2. Инициализация BMP280
  // Пробуем адрес 0x76 (по умолчанию) или 0x77
  if (!bmp.begin(0x76)) {
    if (!bmp.begin(0x77)) {
      display.clearDisplay();
      display.setCursor(0,0);
      display.println("BMP280 Error!");
      display.display();
      while (1); // Останавливаемся, если датчик не найден
    }
  }

  // Настройки сенсора: 16-кратное усреднение для максимального снижения шума
  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL,     
                  Adafruit_BMP280::SAMPLING_X16,     // Температура
                  Adafruit_BMP280::SAMPLING_X16,     // Давление
                  Adafruit_BMP280::FILTER_X16,       // Фильтр
                  Adafruit_BMP280::STANDBY_MS_500);  // Частота обновления

  display.clearDisplay();
  display.setCursor(0,0);
  display.println("System READY");
  display.display();
  delay(1000);

  BTSerial.println("SYSTEM:READY");
}

void loop() {
  // 1. Чтение данных с датчика
  float pressure = bmp.readPressure(); // Давление в Паскалях
  float temperature = bmp.readTemperature(); // Температура в Цельсиях
  unsigned long timestamp = millis(); // Время работы в миллисекундах

  // 2. Вывод на OLED-экран
  display.clearDisplay();

  display.setCursor(0, 0);
  display.setTextSize(1);
  display.print("TIME: ");
  display.print(timestamp / 1000); // В секундах
  display.println(" s");

  display.setCursor(0, 16);
  display.setTextSize(1);
  display.print("Pressure:");

  display.setCursor(0, 26);
  display.setTextSize(2); // Крупный шрифт для давления
  display.print(pressure, 2);
  display.println(" Pa");

  display.setCursor(0, 48);
  display.setTextSize(1);
  display.print("Temp: ");
  display.print(temperature, 2);
  display.print(" C");

  display.display(); // Показать на экране

  // 3. Отправка данных по Bluetooth на смартфон в формате из работы
  // Формат: TIMESTAMP;PRESSURE_PA;TEMPERATURE_C
  BTSerial.print(timestamp);
  BTSerial.print(";");
  BTSerial.print(pressure, 2);
  BTSerial.print(";");
  BTSerial.println(temperature, 2);

  // Задержка 1 секунда (для пеших измерений этого достаточно)
  delay(1000);
}
